/* MedicCare.module.css */
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #E9ECEF;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000;
  --vt-accent-ink: #1a5bbf;
  --vt-accent-on-deep: #247cff;
  --vt-line: #EAEAEA;

  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  overflow-x: hidden;
}

/* === NAVIGATION === */
.navToggle {
  display: none;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 .125rem .25rem rgba(0, 0, 0, .075);
  padding: 0;
  margin: 0;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 94px;
}

.navToggleLabel {
  display: none; /* hidden on desktop */
  cursor: pointer;
  padding: 10px;
}

.navToggleIcon {
  display: block;
  width: 30px;
  height: 2px;
  background: var(--vt-ink);
  position: relative;
  transition: background 0.3s;
}

.navToggleIcon::before,
.navToggleIcon::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  width: 30px;
  height: 2px;
  background: var(--vt-ink);
  transition: top 0.3s, transform 0.3s;
}

.navToggleIcon::before {
  top: -8px;
}

.navToggleIcon::after {
  top: 8px;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-grow: 1;
  justify-content: center;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  padding: 5px 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus-visible {
  color: var(--vt-ink);
}

.brandLink {
  text-decoration: none;
  display: inline-block;
  margin-left: 30px;
}

.brand {
  font-size: 24px;
  font-weight: 700;
  color: var(--vt-accent);
  line-height: 1.2;
  text-align: center;
}

/* === HERO === */
.hero {
  padding-top: 0;
}

.heroContainer {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.heroSlides {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, .15);
}

.heroTitle {
  font-size: 48px;
  font-weight: 700;
  color: var(--vt-ink);
  margin: 0 0 8px;
  line-height: 1.2;
}

.heroPara {
  color: var(--vt-ink-soft);
  font-size: 18px;
  line-height: 1.6;
  margin-bottom: 20px;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  transition: background-color 0.3s, color 0.3s;
}

.customLink:hover {
  background: var(--vt-line);
  color: var(--vt-accent);
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink-soft);
  margin: 0;
}

/* === ABOUT === */
.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.about {
  padding: 7rem 0;
}

.sectionTitle {
  font-size: 36px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 3rem;
  text-align: left;
}

.aboutText {
  color: var(--vt-ink-soft);
  font-size: 18px;
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

/* === GALLERY === */
.gallery {
  padding: 0;
}

.galleryContainer {
  max-width: 100%;
}

.galleryRow {
  display: flex;
}

.galleryItem {
  flex: 1;
  margin: 0;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

/* === TIMELINE === */
.timeline {
  padding: 7rem 0 0;
}

.timelineTrack {
  position: relative;
  margin-bottom: 0;
}

.timelineTrack::before {
  content: '';
  position: absolute;
  top: 37px;
  left: 50%;
  transform: translateX(-50%);
  width: 1px;
  height: 85%;
  background: var(--vt-line);
  z-index: 1;
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  margin-bottom: 4rem;
  position: relative;
}

.timelineNode:last-child {
  margin-bottom: 0;
}

.timelineNode.odd {
  flex-direction: row;
}

.timelineNode.even {
  flex-direction: row-reverse;
}

.timelineDate {
  flex: 1;
  padding: 1rem 0;
  color: var(--vt-ink-soft);
  font-size: 16px;
}

.timelineNode.odd .timelineDate {
  text-align: left;
}

.timelineNode.even .timelineDate {
  text-align: right;
}

.timelineIcon {
  flex: 0 0 80px;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  z-index: 2;
}

.timelineIcon::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, .175);
  z-index: 1;
}

.timelineIcon i {
  position: relative;
  z-index: 2;
  font-size: 32px;
  color: var(--vt-accent);
}

.timelineContent {
  flex: 1;
  background: var(--vt-surface);
  box-shadow: 0 .5rem 1rem rgba(0, 0, 0, .15);
  border-radius: 0 0 .25rem .25rem;
  padding: 0;
  position: relative;
}

.timelineContent h3 {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: .25rem .25rem 0 0;
  position: relative;
  font-size: 20px;
  font-weight: 700;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
  color: var(--vt-ink-soft);
}

.timelineNode.odd .timelineContent h3,
.timelineNode.odd .timelineContent p {
  text-align: right;
}

.timelineNode.even .timelineContent h3,
.timelineNode.even .timelineContent p {
  text-align: left;
}

.timelineNode.odd .timelineContent h3::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border-left: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.even .timelineContent h3::after {
  content: '';
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border-right: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* === FOOTER === */
.footer {
  background: var(--vt-surface-2);
  padding: 7rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 30px;
}

.footerCol {
  flex: 1 1 300px;
}

.footerCol h5 {
  font-size: 20px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.footerCol p {
  color: var(--vt-ink-soft);
  margin-bottom: 0.5rem;
  line-height: 1.6;
}

.footerCol a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.footerCol a:hover {
  color: var(--vt-accent);
}

.socialLinks {
  display: flex;
  gap: 10px;
}

.copyright {
  margin-top: 3rem;
  text-align: center;
  color: var(--vt-ink-soft);
}

.copyright p {
  margin: 0;
}

/* === RESPONSIVE === */
@media screen and (min-width: 1600px) {
  .heroContainer {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .navIn {
    min-height: 74px;
  }

  .navToggleLabel {
    display: block;
  }

  .navLinks {
    display: none;
    position: absolute;
    top: 74px;
    left: 0;
    right: 0;
    background: var(--vt-surface);
    flex-direction: column;
    padding: 20px;
    box-shadow: 0 .5rem 1rem rgba(0, 0, 0, .15);
  }

  .navToggle:checked ~ .nav .navLinks {
    display: flex;
  }

  .navIn {
    position: relative;
  }

  .heroContainer {
    height: inherit;
  }

  .heroText {
    position: relative;
    bottom: 0;
    right: 0;
    width: auto;
    margin-bottom: 0;
    padding: 2rem;
  }

  .heroTitle {
    font-size: 38px;
  }

  .sectionTitle {
    font-size: 32px;
  }

  .timelineTrack::before {
    left: 33px;
    transform: none;
  }

  .timelineNode,
  .timelineNode.odd,
  .timelineNode.even {
    flex-direction: column;
    align-items: flex-start;
  }

  .timelineDate {
    text-align: left !important;
    padding-left: 60px;
  }

  .timelineIcon {
    position: absolute;
    left: 0;
    top: 60px;
    flex-basis: auto;
  }

  .timelineIcon::before {
    width: 75px;
    height: 75px;
  }

  .timelineContent {
    width: 100%;
    margin-left: 60px;
  }

  .timelineNode.odd .timelineContent h3,
  .timelineNode.odd .timelineContent p,
  .timelineNode.even .timelineContent h3,
  .timelineNode.even .timelineContent p {
    text-align: left;
  }

  .timelineNode.odd .timelineContent h3::after,
  .timelineNode.even .timelineContent h3::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-ink);
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .heroTitle {
    font-size: 32px;
  }

  .about {
    padding: 5rem 0;
  }

  .timeline {
    padding-top: 5rem;
  }

  .footer {
    padding: 5rem 0;
  }

  .galleryRow {
    flex-direction: column;
  }

  .galleryItem {
    flex: none;
  }
}

@media screen and (max-width: 575px) {
  .timelineTrack::before {
    left: 57px;
  }

  .timelineIcon {
    left: -10px;
  }

  .timelineIcon::before {
    width: 70px;
    height: 70px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}
